#include HEADER
#include <cstdint>
#include <iostream>
#include <vector>
#include <cstdlib>
std::size_t checks=0;
void require(bool b){++checks;if(!b)std::abort();}
void cycle(std::size_t mu,std::size_t lambda,bool alias){
 std::vector<std::shared_ptr<Node>> nodes(mu+lambda);for(auto&n:nodes)n=make_node();for(std::size_t i=1;i<nodes.size();++i)nodes[i-1]->n=nodes[i];nodes.back()->n=nodes[mu];
 auto parent=make_node(nodes.front());auto head=nodes.front();auto other=head;
 std::vector<long>refs;for(auto&n:nodes)refs.push_back(n.use_count());
 require(break_cycle(alias?parent->n:head));require(head==other&&parent->n==head);
 for(std::size_t i=0;i<nodes.size();++i){require(nodes[i]->n==(i+1<nodes.size()?nodes[i+1]:nullptr));require(nodes[i].use_count()==refs[i]-(i==mu));}
 require(chain_size(head)==nodes.size());require(!break_cycle(head));
}
void cycle_member(std::size_t lambda){
 auto head=make_chain(lambda);std::vector<std::weak_ptr<Node>>weak;Node*last=nullptr;for(auto p=head;p;p=p->n){last=p.get();weak.push_back(p);}
 last->n=head;head.reset();
 require(break_cycle(last->n));for(auto&w:weak)require(w.expired());
}
int main(){
 for(std::size_t mu=0;mu<=128;++mu)for(std::size_t lambda=1;lambda<=128;++lambda)cycle(mu,lambda,(mu+lambda)&1);
 for(std::size_t n=0;n<=256;++n){auto head=make_chain(n);require(!break_cycle(head));require(chain_size(head)==n);}
 for(std::size_t lambda=1;lambda<=256;++lambda)cycle_member(lambda);
 std::cout<<"PASS "<<checks<<" model checks; mu=0..128 lambda=1..128; 256 owning-member cycles\n";
}

