#include HEADER
#include <algorithm>
#include <chrono>
#include <cstdint>
#include <cstdlib>
#include <iomanip>
#include <iostream>
#include <numeric>
#include <random>
#include <vector>
int main(int argc,char**argv){
 if(argc!=5)return 2;std::size_t mu=std::strtoull(argv[1],nullptr,0),lambda=std::strtoull(argv[2],nullptr,0);const std::size_t reps=std::strtoull(argv[3],nullptr,0);const bool shuffled=std::atoi(argv[4]);const auto n=mu+lambda;
 std::vector<std::shared_ptr<Node>>nodes(n);for(auto&node:nodes)node=make_node();std::vector<std::size_t>order(n);std::iota(order.begin(),order.end(),0);if(shuffled){std::mt19937 rng(80395499);std::shuffle(order.begin(),order.end(),rng);}
 for(std::size_t i=1;i<n;++i)nodes[order[i-1]]->n=nodes[order[i]];
 std::shared_ptr<Node>head=n?nodes[order[0]]:nullptr;Node*last=n?nodes[order.back()].get():nullptr;std::shared_ptr<Node>entry=lambda?nodes[order[mu]]:nullptr;std::uint64_t sum=0;
 if(lambda){last->n=entry;if(cycle_entry(head)!=entry.get())return 3;last->n.reset();}else if(cycle_entry(head)!=nullptr)return 4;
 const auto begin=std::chrono::steady_clock::now();
 for(std::size_t rep=0;rep<reps;++rep){if(lambda)last->n=entry;sum+=break_cycle(head);}
 const auto end=std::chrono::steady_clock::now();
 if(sum!=(lambda?reps:0)||chain_size(head)!=n)return 5;
 for(std::size_t i=0;i<n;++i)if(nodes[order[i]]->n!=(i+1<n?nodes[order[i+1]]:nullptr))return 6;
 const double ns=std::chrono::duration<double,std::nano>(end-begin).count();std::cout<<std::setprecision(17)<<ns<<' '<<sum+n<<'\n';
}

