from pathlib import Path
import subprocess,json,hashlib,random,statistics,shutil,fcntl
b=Path(__file__).resolve().parent;variants=['baseline','control','predecessor'];work=[]
for mu,lam in [(0,0),(1,0),(32,0),(0,1),(0,2),(1,1),(2,1),(1,2),(8,1),(1,8),(32,32),(100000,0),(0,100000),(1,99999),(99999,1),(50000,50000),(100000,2),(100000,100000),(500000,500000)]:
 for shuffled in ([0,1]if mu+lam>=100000 and mu+lam<=200000 else[0]):work.append((mu,lam,100000 if mu+lam<100 else 10 if mu+lam<=200000 else 1,shuffled))
d={'cpu':18,'build':[],'rows':[],'summary':{},'workloads':work,'samples':7,'variants':variants,'flags':'-std=c++23 -O2 -DSKIP_RUNTIME_CHECKS'}
for cc,compiler in [('gcc',['/usr/bin/g++']),('clang',['/usr/bin/clang++','--gcc-install-dir=/usr/lib/gcc/x86_64-linux-gnu/15'])]:
 for v in variants:
  exe=b/(cc+'-'+v)
  if v=='control':shutil.copyfile(b/(cc+'-baseline'),exe);exe.chmod(0o755);cmd=None
  else:
   cmd=['taskset','-c','22',*compiler,'-std=c++23','-O2','-DSKIP_RUNTIME_CHECKS','-DHEADER="'+str(b/(v+'.hpp'))+'"',str(b/'bench.cpp'),'-o',str(exe)];p=subprocess.run(cmd,capture_output=True);assert not p.returncode and not p.stderr,p.stderr.decode()
  d['build'].append({'compiler':cc,'variant':v,'command':cmd,'sha256':hashlib.sha256(exe.read_bytes()).hexdigest()})
 print('compiled',cc,flush=True)
with open('/tmp/sirkit_node_break18.lock','w')as lock:
 fcntl.flock(lock,fcntl.LOCK_EX)
 for cc in ['gcc','clang']:
  for i,(mu,lam,reps,shuffled)in enumerate(work):
   for rep in range(d['samples']):
    vs=variants.copy();random.Random(i*31+rep).shuffle(vs);sums=set()
    for v in vs:
     q=subprocess.check_output(['taskset','-c','18',str(b/(cc+'-'+v)),str(mu),str(lam),str(reps),str(shuffled)],text=True).split();sums.add(q[1]);d['rows'].append({'compiler':cc,'variant':v,'mu':mu,'lambda':lam,'shuffled':shuffled,'reps':reps,'round':rep,'ns':float(q[0]),'checksum':q[1]})
    assert len(sums)==1
  ss={}
  for mu,lam,reps,shuffled in work:
   med={v:statistics.median(x['ns']for x in d['rows']if x['compiler']==cc and x['variant']==v and x['mu']==mu and x['lambda']==lam and x['shuffled']==shuffled)for v in variants};ss[f'mu{mu}_lambda{lam}_shuffled{shuffled}']={'median_ns':med,'ratio':med['predecessor']/med['baseline'],'control_ratio':med['control']/med['baseline']}
  d['summary'][cc]=ss;(b/'results.json').write_text(json.dumps(d,indent=2)+'\n');print('measured',cc,flush=True)

