b=Path(__file__).resolve().parent;r=Path('/home/reinsirk/Atcoder_Env');f=json.loads((b/'frozen-hashes.json').read_text())
for p,h in f.items():assert hashlib.sha256((r/p).read_bytes()).hexdigest()==h,p;(b/Path(p).name).write_bytes((r/p).read_bytes())
program=(b/'node_reachable.cpp').read_text();baseline=(b/'baseline.hpp').read_text();assert program.count(baseline)==1
for v in ['baseline','predecessor']:(b/('main-'+v+'.cpp')).write_text(program.replace(baseline,(b/(v+'.hpp')).read_text(),1))
cases=[]
def add(name,a,start):
 n=len(a);assert n>=2 and all(0<=x<n and x!=i for i,x in enumerate(a));seen=set();x=start
 while x not in seen:seen.add(x);x=a[x]
 text=f'{n} {start+1}\n'+ ' '.join(str(x+1)for x in a)+'\n';cases.append({'name':name,'input':text.encode(),'expected':str(len(seen))+'\n'})
n=100000;add('cycle',[i+1 for i in range(n-1)]+[0],0);add('prefix_1_long_cycle',[i+1 for i in range(n-1)]+[1],0);add('prefix_long_cycle_2',[i+1 for i in range(n-1)]+[n-2],0);add('prefix_half_cycle_half',[i+1 for i in range(n-1)]+[n//2],0)
add('disconnected_pairs',[i^1 for i in range(n)],n-1);rng=random.Random(80395499)
a=[]
for i in range(n):x=rng.randrange(n-1);a.append(x+(x>=i))
add('random_large',a,rng.randrange(n))
order=list(range(n));rng.shuffle(order);a=[0]*n
for i in range(n-1):a[order[i]]=order[i+1]
a[order[-1]]=order[1];add('shuffled_prefix_1_long_cycle',a,order[0])
d={'cpu':18,'frozen_hashes':f,'build':[],'rows':[],'summary':{},'same_main':True,'same_io':True,'inputs':[{'name':x['name'],'sha256':hashlib.sha256(x['input']).hexdigest(),'bytes':len(x['input']),'expected':x['expected']}for x in cases],'oracle':'independent integer visited set, no Node helper'}
for cc,compiler in [('gcc',['/usr/bin/g++']),('clang',['/usr/bin/clang++','--gcc-install-dir=/usr/lib/gcc/x86_64-linux-gnu/15'])]:
 for v in ['baseline','control','predecessor']:
  exe=b/(cc+'-main-'+v)
  if v=='control':shutil.copyfile(b/(cc+'-main-baseline'),exe);exe.chmod(0o755);cmd=None
  else:
   cmd=['taskset','-c','22',*compiler,'-std=c++23','-O2',str(b/('main-'+v+'.cpp')),'-o',str(exe)];p=subprocess.run(cmd,capture_output=True);assert not p.returncode and not p.stderr,p.stderr.decode()
  d['build'].append({'compiler':cc,'variant':v,'command':cmd,'sha256':hashlib.sha256(exe.read_bytes()).hexdigest()})
 print('compiled main',cc,flush=True)
import time
with open('/tmp/sirkit_node_break18.lock','w')as lock:
 fcntl.flock(lock,fcntl.LOCK_EX)
 for cc in ['gcc','clang']:
  for i,case in enumerate(cases):
   for rep in range(9):
    vs=['baseline','control','predecessor'];random.Random(i*31+rep).shuffle(vs)
    for v in vs:
     begin=time.perf_counter_ns();q=subprocess.run(['taskset','-c','18',str(b/(cc+'-main-'+v))],input=case['input'],capture_output=True);ns=time.perf_counter_ns()-begin;assert not q.returncode and not q.stderr and q.stdout.decode()==case['expected'],(cc,v,case['name'],q.stderr,q.stdout)
     d['rows'].append({'compiler':cc,'variant':v,'case':case['name'],'round':rep,'ns':ns,'output':q.stdout.decode()})
  ss={}
  for case in cases:
   med={v:statistics.median(x['ns']for x in d['rows']if x['compiler']==cc and x['variant']==v and x['case']==case['name'])for v in ['baseline','control','predecessor']};ss[case['name']]={'median_ns':med,'ratio':med['predecessor']/med['baseline'],'control_ratio':med['control']/med['baseline']}
  d['summary'][cc]=ss;(b/'main-results.json').write_text(json.dumps(d,indent=2)+'\n');print('measured main',cc,flush=True)

