bench.cpp.source:
#include HEADER
#include <algorithm>
#include <chrono>
#include <cstddef>
#include <cstdint>
#include <cstdlib>
#include <iostream>
#include <memory>
#include <string>
#include <vector>

[[gnu::noinline]] Node* entry_call(const std::shared_ptr<Node>& head) {
    asm volatile("" ::: "memory");
    return cycle_entry(head);
}
[[gnu::noinline]] bool break_call(const std::shared_ptr<Node>& head) {
    asm volatile("" ::: "memory");
    return break_cycle(head);
}
int main(int argc, char** argv) {
    if (argc != 6) return 2;
    const std::string operation = argv[1];
    const auto prefix = static_cast<std::size_t>(std::strtoull(argv[2], nullptr, 0));
    const auto period = static_cast<std::size_t>(std::strtoull(argv[3], nullptr, 0));
    const auto repetitions = static_cast<std::size_t>(std::strtoull(argv[4], nullptr, 0));
    const bool owning_null = std::atoi(argv[5]) != 0;
    const auto count = prefix + period;
    std::vector<std::shared_ptr<Node>> nodes;
    nodes.reserve(count);
    for (std::size_t i = 0; i < count; ++i) nodes.push_back(make_node());
    for (std::size_t i = 1; i < count; ++i) nodes[i-1]->n = nodes[i];
    std::size_t deleted = 0;
    if (count && period) nodes.back()->n = nodes[prefix];
    else if (count && owning_null) nodes.back()->n = std::shared_ptr<Node>(nullptr, [&deleted](Node*) { ++deleted; });
    std::shared_ptr<Node> head = count ? nodes.front() : nullptr;
    Node* expected = period ? nodes[prefix].get() : nullptr;
    std::uint64_t checksum = 0;
    const auto start = std::chrono::steady_clock::now();
    if (operation == "entry") {
        for (std::size_t i = 0; i < repetitions; ++i) {
            Node* found = entry_call(head);
            if (found != expected) return 3;
            checksum += found != nullptr;
        }
    } else if (operation == "break") {
        for (std::size_t i = 0; i < repetitions; ++i) {
            if (period) nodes.back()->n = nodes[prefix];
            const bool found = break_call(head);
            if (found != (period != 0)) return 4;
            checksum += found;
        }
    } else return 5;
    const auto stop = std::chrono::steady_clock::now();
    if (count) nodes.back()->n.reset();
    head.reset();
    nodes.clear();
    if (deleted != static_cast<std::size_t>(count && !period && owning_null)) return 6;
    std::cout << std::chrono::duration<double, std::nano>(stop-start).count() << ' ' << checksum << '\n';
}

