#include HEADER
#include <atomic>
#include <chrono>
#include <cstdint>
#include <cstdlib>
#include <iostream>
int main(int argc, char** argv) {
    if (argc != 4) return 2;
    const auto prefix = std::strtoull(argv[1], nullptr, 0);
    const auto period = std::strtoull(argv[2], nullptr, 0);
    const auto repeats = std::strtoull(argv[3], nullptr, 0);
    auto head = make_chain(prefix + period);
    auto tail = chain_tail(head);
    auto entry = period ? chain_nth(head, prefix) : nullptr;
    if (period) tail->n = entry;
    std::uint64_t sum = 0;
    const auto begin = std::chrono::steady_clock::now();
    for (std::size_t i = 0; i < repeats; ++i) {
        std::atomic_signal_fence(std::memory_order_acq_rel);
        sum += has_cycle(head);
    }
    const auto end = std::chrono::steady_clock::now();
    break_cycle(head);
    std::cout << std::chrono::duration<double, std::nano>(end-begin).count() << ' ' << sum << '\n';
}

